# Created by OpenAI
from triton.experimental import gluon
from triton.experimental.gluon import language as gl

@gluon.jit
def _exp_mode(x, FAST: gl.constexpr):
    if FAST:
        return gl.exp2(x * 1.4426950408889634)
    else:
        return gl.exp(x)

@gluon.jit
def _qk_operands(q, k, acc, NATIVE: gl.constexpr):
    if NATIVE:
        return gl.amd.cdna4.mfma_scaled(q, None, 'e4m3', k, None, 'e4m3', acc)
    else:
        return gl.amd.cdna4.mfma(q, k.to(gl.bfloat16), acc)
